#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    double trimMean(vector<int>& arr) {
        sort(arr.begin(), arr.end());
        int n = arr.size();
        int k = n / 20;
        double sum = 0;
        for (int i = k; i < n - k; ++i) {
            sum += arr[i];
        }
        return sum / (n - 2 * k);
    }
};

import java.util.*;

class Solution {
    public double trimMean(int[] arr) {
        Arrays.sort(arr);
        int n = arr.length;
        int k = n / 20;
        double sum = 0;
        for (int i = k; i < n - k; ++i) {
            sum += arr[i];
        }
        return sum / (n - 2 * k);
    }
}

/**
 * @param {number[]} arr
 * @return {number}
 */
var trimMean = function(arr) {
    arr.sort((a, b) => a - b);
    const n = arr.length;
    const k = Math.floor(n / 20);
    let sum = 0;
    for (let i = k; i < n - k; ++i) {
        sum += arr[i];
    }
    return sum / (n - 2 * k);
};
